-- [37/84] V2026_09_08_01__sum_daily_full_channel_class.sql
-- -------------------------------------------------------------------------------------------
SET search_path = public;
SELECT EXISTS (SELECT 1 FROM public.schema_migration_log WHERE filename = 'V2026_09_08_01__sum_daily_full_channel_class.sql') AS acq_done,
       false AS acq_superseded \gset
\if :acq_done
\echo '  [skip ] V2026_09_08_01__sum_daily_full_channel_class.sql'
\elif :acq_superseded
\echo '  [supersd] V2026_09_08_01__sum_daily_full_channel_class.sql - a later migration that replaces it is already applied; recorded, not run'
INSERT INTO public.schema_migration_log (filename) VALUES ('V2026_09_08_01__sum_daily_full_channel_class.sql') ON CONFLICT (filename) DO NOTHING;
\else
\echo '  [apply] V2026_09_08_01__sum_daily_full_channel_class.sql'
BEGIN;
-- ============================================================================
-- V2026_09_08_01: normalized channel_class (POS/ECOM) on sum_daily_full.
--
-- WHY
-- ---
-- The executive screens gain a POS / ECOM / All channel selector (user,
-- 2026-09-08). Their source table sum_daily_merchant has no channel dimension,
-- so channel-filtered reads route to sum_daily_full (ChannelSql.merchantDay) -
-- but sum_daily_full.channel holds the RAW terminal type ('PAX A920',
-- 'BENEFIT PG', 'MPGS', ...), not the normalized channel. This adds a
-- channel_class column with the terminal_channel_map resolution applied once
-- at write time, so read queries filter on a plain indexed-prunable equality
-- instead of re-resolving the map per row.
--
-- DESIGN
-- ------
-- * channel_class is FUNCTIONALLY DEPENDENT on (tenant, channel): the raw
--   terminal type determines the class via terminal_channel_map. It is NOT
--   part of the unique key - no grain change, no rebuild required for
--   correctness (this migration backfills every existing row).
-- * Backfill resolution mirrors the ingest fee pass: tenant-specific map row
--   beats country row, exact raw_type beats the '*' wildcard, unmatched
--   defaults to 'POS' (same COALESCE the population SQL uses).
-- * Going forward SummaryPopulationService stamps channel_class from
--   fact_transaction.channel (the ingest-stamped truth), falling back to the
--   same map lookup for pre-stamp fact rows, so a rebuild of old months can
--   never regress a correct class to the 'POS' default.
--
-- Idempotent; splitter-safe (no dollar-quoting, no DO blocks). The backfill
-- UPDATE only touches rows where channel_class IS NULL, so re-runs are no-ops.
-- ============================================================================

ALTER TABLE sum_daily_full ADD COLUMN IF NOT EXISTS channel_class VARCHAR(10) NULL;

COMMENT ON COLUMN sum_daily_full.channel_class IS
  'Normalized channel (POS/ECOM) resolved from the raw terminal type in `channel` via terminal_channel_map. Functionally dependent on (tenant, channel) - not part of the grain. Read path for the executive POS/ECOM selector (ChannelSql).';

-- One-time backfill of existing rows. Correlated lookup per DISTINCT
-- (tenant, raw type) value is fine: the map is tiny and the planner caches
-- the subplan; this scans each partition once.
UPDATE sum_daily_full s SET channel_class = COALESCE(
  (SELECT mm.channel FROM terminal_channel_map mm
    WHERE mm.country_code = (SELECT tt.home_country_code FROM tenant tt
                             WHERE tt.tenant_id = s.tenant_id)
      AND (mm.tenant_id IS NULL OR mm.tenant_id = s.tenant_id)
      AND (mm.raw_type = UPPER(TRIM(COALESCE(s.channel, ''))) OR mm.raw_type = '*')
    ORDER BY (mm.tenant_id IS NULL), (mm.raw_type = '*')
    LIMIT 1),
  'POS')
WHERE s.channel_class IS NULL;

-- Verify: every row classed, and the split looks sane per tenant.
SELECT tenant_id, channel_class, COUNT(*) rows, SUM(total_volume) volume
FROM sum_daily_full GROUP BY tenant_id, channel_class ORDER BY tenant_id, channel_class;

INSERT INTO schema_migration_log (filename) VALUES ('V2026_09_08_01__sum_daily_full_channel_class.sql') ON CONFLICT (filename) DO NOTHING;
;
INSERT INTO public.schema_migration_log (filename) VALUES ('V2026_09_08_01__sum_daily_full_channel_class.sql') ON CONFLICT (filename) DO NOTHING;
COMMIT;
\endif

-- -------------------------------------------------------------------------------------------
-- [38/84] V2026_09_10_01__digest_trx_only_mandatory.sql
-- -------------------------------------------------------------------------------------------
SET search_path = public;
SELECT EXISTS (SELECT 1 FROM public.schema_migration_log WHERE filename = 'V2026_09_10_01__digest_trx_only_mandatory.sql') AS acq_done,
       false AS acq_superseded \gset
\if :acq_done
\echo '  [skip ] V2026_09_10_01__digest_trx_only_mandatory.sql'
\elif :acq_superseded
\echo '  [supersd] V2026_09_10_01__digest_trx_only_mandatory.sql - a later migration that replaces it is already applied; recorded, not run'
INSERT INTO public.schema_migration_log (filename) VALUES ('V2026_09_10_01__digest_trx_only_mandatory.sql') ON CONFLICT (filename) DO NOTHING;
\else
\echo '  [apply] V2026_09_10_01__digest_trx_only_mandatory.sql'
BEGIN;
-- ============================================================================
-- V2026_09_10_01: Daily Digest — transactions are the ONLY mandatory feed.
--
-- Symptom: a bank that only loads transactions never saw its digest send —
-- the day sat PENDING with waiting_on = 'DCC+RENTAL' (and 'MERCHANT') forever,
-- because DCC / rental / merchant all defaulted to required = TRUE and those
-- feeds simply never arrive for that tenant.
--
-- Decision (2026-09-10): only require_trx is mandatory; DCC, rental and
-- merchant become OPTIONAL — off by default, an admin turns them on per tenant
-- if the bank actually receives that feed. This flips the stored defaults AND
-- unblocks every currently-held day.
--
-- Idempotent; splitter-safe (no $$). On prod apply once via psql.
-- ============================================================================

-- 1. New-tenant defaults: only transactions stays TRUE.
ALTER TABLE digest_config ALTER COLUMN require_dcc      SET DEFAULT FALSE;
ALTER TABLE digest_config ALTER COLUMN require_rental   SET DEFAULT FALSE;
ALTER TABLE digest_config ALTER COLUMN require_merchant SET DEFAULT FALSE;
ALTER TABLE digest_config ALTER COLUMN require_trx      SET DEFAULT TRUE;

-- 2. Existing tenants: relax the three optional feeds, and make sure
--    transactions is mandatory everywhere.
--
--    ONE-TIME flip, guarded on this migration's own ledger row: after it has
--    run, an admin turning DCC or rental back on for a tenant is a deliberate
--    choice, and re-running this file must not silently undo it. The NOT
--    EXISTS makes the re-run a no-op (and keeps the file splitter-safe — no
--    DO block / $$).
UPDATE digest_config
   SET require_dcc      = FALSE,
       require_rental   = FALSE,
       require_merchant = FALSE,
       require_trx      = TRUE
 WHERE NOT EXISTS (
       SELECT 1 FROM schema_migration_log
        WHERE filename = 'V2026_09_10_01__digest_trx_only_mandatory.sql');

-- 3. Unblock days already held only by the now-optional feeds. Clearing
--    waiting_on lets the next sweep re-gate them against transactions alone;
--    a day still missing transactions will simply be re-flagged 'TRX'.
UPDATE digest_dispatch
   SET waiting_on = NULL
 WHERE status = 'PENDING'
   AND waiting_on IS NOT NULL
   AND waiting_on NOT LIKE '%TRX%';

INSERT INTO schema_migration_log (filename) VALUES ('V2026_09_10_01__digest_trx_only_mandatory.sql') ON CONFLICT (filename) DO NOTHING;
;
INSERT INTO public.schema_migration_log (filename) VALUES ('V2026_09_10_01__digest_trx_only_mandatory.sql') ON CONFLICT (filename) DO NOTHING;
COMMIT;
\endif

