        AND COALESCE(x.tenant_id, 0) = COALESCE(s.tenant_id, 0)
        AND x.dest = s.dest AND x.channel = s.channel
        AND x.scheme_group = s.scheme_group
        AND x.effective_from = DATE '2026-10-01');

