       k.card_type, t.tier, NULL, m.mcc, NULL, NULL,
       CASE c.channel WHEN 'POS' THEN t.pos_pct ELSE t.ecom_pct END, 0.0000, 200.0000, 'APPROVED', NULL,
       'EG Visa MCC ' || m.mcc || ' ' || m.industry || ' ' || t.product || ' ' || c.channel || ' ' || k.card_type || ' cap EGP 200',
