SELECT NULL, 'EG', 'EGP', 55, 'DOMESTIC', NULL, 'Visa',
       k.card_type, NULL, NULL, m.mcc, NULL, 600.0100,
       0.000000, 1.5000, NULL, 'APPROVED', NULL,
       'EG Visa MCC ' || m.mcc || ' ' || m.industry || ' ' || k.card_type || ' <= EGP 600 flat EGP 1.50',
