-- -------------------------------------------------------------------------------------------
SET search_path = public;
SELECT EXISTS (SELECT 1 FROM public.schema_migration_log WHERE filename = 'V2026_10_26_05__eg_meeza_interchange_reassert.sql') AS acq_done,
       false AS acq_superseded \gset
